struct FNWWeatherProvider: TimelineProvider {
  func placeholder(in context: Context) -> FNWEntry {
    FNWEntry(date: Date(), v: FNW.initialValues["Weather"] ?? [:])
  }

  func getSnapshot(in context: Context, completion: @escaping (FNWEntry) -> Void) {
    completion(FNWEntry(date: Date(), v: FNW.values("Weather", at: Date(), timeline: FNW.timeline("Weather"), options: [("city", "Cairo")])))
  }

  func getTimeline(in context: Context, completion: @escaping (Timeline<FNWEntry>) -> Void) {
    Task {
      await FNW.refresh("Weather", FNWWeatherRefresh, options: [("city", "Cairo")])
      completion(FNW.entries("Weather", clock: false, liveDate: false, timers: [], options: [("city", "Cairo")], refreshEvery: 1800))
    }
  }
}

@available(iOS 17, *)
enum FNWWeatherCityOption: String, AppEnum {
  case c0 = "Cairo"
  case c1 = "Giza"
  static var typeDisplayRepresentation: TypeDisplayRepresentation = "City"
  static var caseDisplayRepresentations: [FNWWeatherCityOption: DisplayRepresentation] = [
    .c0: "Cairo",
    .c1: "Giza",
  ]
}

@available(iOS 17, *)
struct FNWWeatherConfiguration: WidgetConfigurationIntent {
  static var title: LocalizedStringResource = "Weather"

  @Parameter(title: "City", default: .c0)
  var fnw_city: FNWWeatherCityOption

  var fnwOptions: [(String, String)] {
    [("city", fnw_city.rawValue)]
  }
}

@available(iOS 17, *)
struct FNWWeatherConfigurableProvider: AppIntentTimelineProvider {
  func placeholder(in context: Context) -> FNWEntry {
    FNWEntry(date: Date(), v: FNW.initialValues["Weather"] ?? [:])
  }

  func snapshot(for configuration: FNWWeatherConfiguration, in context: Context) async -> FNWEntry {
    FNWEntry(date: Date(), v: FNW.values("Weather", at: Date(), timeline: FNW.timeline("Weather"), options: configuration.fnwOptions))
  }

  func timeline(for configuration: FNWWeatherConfiguration, in context: Context) async -> Timeline<FNWEntry> {
    await FNW.refresh("Weather", FNWWeatherRefresh, options: configuration.fnwOptions)
    return FNW.entries("Weather", clock: false, liveDate: false, timers: [], options: configuration.fnwOptions, refreshEvery: 1800)
  }
}

struct FNWWeatherView: View {
  let entry: FNWEntry

  var body: some View {
    content
      .padding(EdgeInsets(top: 12, leading: 12, bottom: 12, trailing: 12))
      .fnwBackground(FNW.color(0xFFFFFFFF, 0xFF1C1C1E))
      .widgetURL(URL(string: "fnw://open?homeWidget&w=Weather"))
  }

  @ViewBuilder var content: some View {
    main
  }

  @ViewBuilder var main: some View {
    Text(verbatim: FNW.resolve("{city} {temp}", entry.v))
      .font(.system(size: 14, weight: .regular))
      .foregroundColor(FNW.color(0xFF1C1C1E, 0xFFF2F2F7))
      .multilineTextAlignment(.leading)
      .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .center)
  }

}

struct FNWWeatherWidget: Widget {
  let kind: String = "Weather"

  var body: some WidgetConfiguration {
    StaticConfiguration(kind: kind, provider: FNWWeatherProvider()) { entry in
      FNWWeatherView(entry: entry)
    }
    .configurationDisplayName("Weather")
    .description("")
    .supportedFamilies([.systemSmall])
    .fnwContentMarginsDisabled()
  }
}

@available(iOS 17, *)
struct FNWWeatherConfigurableWidget: Widget {
  let kind: String = "Weather"

  var body: some WidgetConfiguration {
    AppIntentConfiguration(kind: kind, intent: FNWWeatherConfiguration.self, provider: FNWWeatherConfigurableProvider()) { entry in
      FNWWeatherView(entry: entry)
    }
    .configurationDisplayName("Weather")
    .description("")
    .supportedFamilies([.systemSmall])
    .fnwContentMarginsDisabled()
  }
}

struct FNWWidgetBundle: WidgetBundle {
  var body: some Widget {
    FNWDashboardWidget()
    FNWWeatherWidget()
  }
}

@available(iOS 17, *)
struct FNWWidgetBundle17: WidgetBundle {
  var body: some Widget {
    FNWDashboardWidget()
    FNWWeatherConfigurableWidget()
  }
}

@main
enum FNWWidgetsMain {
  static func main() {
    if #available(iOS 17, *) {
      FNWWidgetBundle17.main()
    } else {
      FNWWidgetBundle.main()
    }
  }
}
